import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

export default function AddProductPage() {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    title: '',
    brand: '',
    category: 'Electronics',
    price: '',
    mrp: '',
    stock: '',
    description: '',
    features: ''
  });
  const [selectedImages, setSelectedImages] = useState([]);
  const [loading, setLoading] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleImageChange = (e) => {
    const files = Array.from(e.target.files);
    if (files.length > 10) {
      alert("You can upload a maximum of 10 images.");
      return;
    }
    setSelectedImages(files);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setLoading(true);

    const data = new FormData();
    data.append('title', formData.title);
    data.append('brand', formData.brand);
    data.append('category', formData.category);
    data.append('price', formData.price);
    data.append('mrp', formData.mrp);
    data.append('stock', formData.stock);
    data.append('description', formData.description);
    
    // Split features by new line into an array
    const featureArray = formData.features.split('\n').filter(f => f.trim() !== '');
    featureArray.forEach(feature => data.append('features', feature));

    // Append up to 10 images
    selectedImages.forEach(file => {
      data.append('images', file);
    });

    try {
      await axios.post('http://localhost:4000/api/seller/products', data, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      alert('Product published successfully!');
      navigate('/seller'); // Redirect back to inventory dashboard
    } catch (err) {
      console.error(err);
      alert('Failed to publish product');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div style={{ padding: '30px', maxWidth: '900px', margin: 'auto', background: '#fff', borderRadius: '8px' }}>
      <h2>Add New Product (Amazon Seller Style)</h2>
      <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
        
        {/* Basic Info */}
        <div>
          <label>Product Title *</label>
          <input type="text" name="title" value={formData.title} onChange={handleChange} required style={{ width: '100%', padding: '8px' }} />
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
          <div>
            <label>Brand / Store Name</label>
            <input type="text" name="brand" value={formData.brand} onChange={handleChange} style={{ width: '100%', padding: '8px' }} />
          </div>
          <div>
            <label>Category</label>
            <select name="category" value={formData.category} onChange={handleChange} style={{ width: '100%', padding: '8px' }}>
              <option value="Electronics">Electronics</option>
              <option value="Home & Kitchen">Home & Kitchen</option>
              <option value="Fashion">Fashion</option>
              <option value="Appliances">Appliances</option>
            </select>
          </div>
        </div>

        {/* Pricing & Stock */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr 1fr', gap: '15px' }}>
          <div>
            <label>Selling Price ($/₹) *</label>
            <input type="number" name="price" value={formData.price} onChange={handleChange} required style={{ width: '100%', padding: '8px' }} />
          </div>
          <div>
            <label>M.R.P ($/₹)</label>
            <input type="number" name="mrp" value={formData.mrp} onChange={handleChange} style={{ width: '100%', padding: '8px' }} />
          </div>
          <div>
            <label>Available Stock *</label>
            <input type="number" name="stock" value={formData.stock} onChange={handleChange} required style={{ width: '100%', padding: '8px' }} />
          </div>
        </div>

        {/* Description & Bullet Features */}
        <div>
          <label>Product Description</label>
          <textarea name="description" rows="4" value={formData.description} onChange={handleChange} style={{ width: '100%', padding: '8px' }} placeholder="Detailed product overview..." />
        </div>

        <div>
          <label>Key Features / Bullet Points (Put each feature on a new line)</label>
          <textarea name="features" rows="4" value={formData.features} onChange={handleChange} style={{ width: '100%', padding: '8px' }} placeholder="e.g. Rechargeable 2W Led Torch&#10;Metallic Finish&#10;Overcharge Protection" />
        </div>

        {/* Up to 10 Images Upload */}
        <div>
          <label>Product Images (Select up to 10 images)</label>
          <input type="file" name="images" multiple accept="image/*" onChange={handleImageChange} style={{ display: 'block', marginTop: '5px' }} />
          <small style={{ color: '#666' }}>{selectedImages.length} image(s) selected (Max 10)</small>
        </div>

        {/* Submit Actions */}
        <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end' }}>
          <button type="button" onClick={() => navigate('/seller')} style={{ padding: '10px 20px', cursor: 'pointer' }}>Cancel</button>
          <button type="submit" disabled={loading} style={{ padding: '10px 20px', background: '#FF9900', color: '#000', fontWeight: 'bold', border: 'none', cursor: 'pointer' }}>
            {loading ? 'Publishing...' : 'Save and Publish Product'}
          </button>
        </div>

      </form>
    </div>
  );
}
